#!/usr/bin/env bun
/**
 * verify-keybindings-template-roundtrip — the bytes generated by
 * \`generateKeybindingsTemplate()\` must validate against
 * \`KeybindingsSchema\`.
 *
 * Bug class this catches: someone adds a new context to
 * DEFAULT_BINDINGS (e.g. 'NewContext') without updating
 * KEYBINDING_CONTEXTS in the schema. The runtime keeps using the new
 * context fine, but the moment the user copies the template into
 * \`~/.claude/keybindings.json\` and triggers /doctor, validation
 * rejects their config — silent UX bug, only surfaces when a user
 * customizes keybindings.
 *
 * Discovery (2026-04-29): caught 3 missing contexts (FormField,
 * Scroll, EffortPicker) and 7 missing scroll/selection actions in
 * defaults. Fixed in d006c2b5.
 */
import { generateKeybindingsTemplate } from '../packages/repl/src/keybindings/template.ts'
import { KeybindingsSchema } from '../packages/repl/src/keybindings/schema.ts'

const tpl = generateKeybindingsTemplate()
let parsed: unknown
try {
  parsed = JSON.parse(tpl)
} catch (e) {
  console.error(
    `verify-keybindings-template-roundtrip: generated template is not valid JSON`,
  )
  console.error(`  parse error: ${e instanceof Error ? e.message : String(e)}`)
  process.exit(1)
}

const result = KeybindingsSchema().safeParse(parsed)
if (!result.success) {
  console.error(
    `verify-keybindings-template-roundtrip: ${result.error.issues.length} schema violation(s)`,
  )
  console.error(
    'The generated template must validate — otherwise users who copy it into ~/.claude/keybindings.json get rejected by /doctor.',
  )
  console.error('')
  for (const issue of result.error.issues.slice(0, 10)) {
    console.error(`  ${issue.code}: ${issue.message}`)
    console.error(`    path: ${issue.path.join('.')}`)
  }
  if (result.error.issues.length > 10) {
    console.error(`  ... and ${result.error.issues.length - 10} more`)
  }
  console.error(
    '\nFix: bring KEYBINDING_CONTEXTS / KEYBINDING_ACTIONS in packages/repl/src/keybindings/schema.ts in sync with DEFAULT_BINDINGS in defaultBindings.ts.',
  )
  process.exit(1)
}

console.log(
  `verify-keybindings-template-roundtrip: ${tpl.length}-byte template validates against schema`,
)
